import re

_PUNCT = r'!"#$%&\'()*+,-./:;<=>?@[\]^_`{|}~'


def unescape(s):
    return html.unescape(re.sub(r'\\([!"#$%&\'()*+,\-./:;<=>?@\[\\\]^_`{|}~])', r'\1', s))


def text_escape(s):
    return html.escape(s, quote=False)


def attr(s):
    return html.escape(str(s), quote=True).replace('&#x27;', '&#39;')


def _close_bracket(s, start):
    depth = 1
    i = start + 1
    while i < len(s):
        if s[i] == '\\':
            i += 2
            continue
        if s[i] == '[':
            depth += 1
        elif s[i] == ']':
            depth -= 1
            if not depth:
                return i
        i += 1
    return None


def destination(s, i):
    """Read a parenthesized destination and optional title."""
    if i >= len(s) or s[i] != '(':
        return None
    i += 1
    while i < len(s) and s[i].isspace():
        i += 1
    start = i
    if i < len(s) and s[i] == '<':
        i += 1
        start = i
        while i < len(s):
            if s[i] == '\\':
                i += 2
            elif s[i] == '>':
                break
            elif s[i] == '\n':
                return None
            else:
                i += 1
        if i >= len(s):
            return None
        url = s[start:i]
        i += 1
    else:
        depth = 0
        while i < len(s):
            c = s[i]
            if c == '\\':
                i += 2
                continue
            if c == '(':
                depth += 1
            elif c == ')':
                if depth == 0:
                    break
                depth -= 1
            elif c.isspace():
                break
            i += 1
        if depth:
            return None
        url = s[start:i]
    before = i
    while i < len(s) and s[i].isspace():
        i += 1
    title = ''
    if i > before and i < len(s) and s[i] in ('"', "'", '('):
        closer = ')' if s[i] == '(' else s[i]
        i += 1
        start = i
        while i < len(s) and s[i] != closer:
            i += 2 if s[i] == '\\' else 1
        if i >= len(s):
            return None
        title = s[start:i]
        i += 1
        while i < len(s) and s[i].isspace():
            i += 1
    if i >= len(s) or s[i] != ')':
        return None
    return unescape(url), unescape(title), i + 1


def references(text):
    refs = {}
    out = []
    for line in text.split('\n'):
        m = re.match(r'^ {0,3}\[([^\]]+)\]:\s*(.*)$', line)
        if m:
            parsed = destination('(' + m.group(2) + ')', 0)
            if parsed:
                refs[' '.join(m.group(1).split()).lower()] = parsed[:2]
                out.append('')
                continue
        out.append(line)
    return '\n'.join(out), refs


def link_at(text, pos, refs):
    image = text.startswith('![', pos)
    start = pos + 1 if image else pos
    if start >= len(text) or text[start] != '[':
        return None
    end = _close_bracket(text, start)
    if end is None:
        return None
    label = text[start + 1:end]
    parsed = destination(text, end + 1)
    if parsed:
        url, title, finish = parsed
        return image, label, url, title, finish
    finish = end + 1
    reference = label
    if finish < len(text) and text[finish] == '[':
        last = _close_bracket(text, finish)
        if last is not None:
            reference = text[finish + 1:last] or label
            finish = last + 1
    value = refs.get(' '.join(reference.split()).lower())
    if value:
        return image, label, value[0], value[1], finish
    return None


def without_code(text):
    out = []
    fence = None
    html_block = False
    for line in text.split('\n'):
        m = re.match(r'^ {0,3}(`{3,}|~{3,})', line)
        if fence:
            if m and m.group(1)[0] == fence[0] and len(m.group(1)) >= len(fence):
                fence = None
            out.append('')
            continue
        if m:
            fence = m.group(1)
            out.append('')
            continue
        if re.match(r'^ {0,3}<(?:div|table|script|style|pre|section|!--)(?:\s|>|$)', line, re.I):
            html_block = True
        if html_block:
            if not line.strip():
                html_block = False
            out.append('')
            continue
        if line.startswith(('    ', '\t')):
            out.append('')
        else:
            out.append(line)
    return '\n'.join(out)


def media_references(text):
    text, refs = references(text)
    text = without_code(text)
    i = 0
    result = []
    while i < len(text):
        if text[i] == '\\' and i + 1 < len(text) and text[i + 1] in _PUNCT:
            i += 2
            continue
        if text[i] == '`':
            match = re.match(r'`+', text[i:])
            mark = match.group(0)
            end = text.find(mark, i + len(mark))
            if end >= 0:
                i = end + len(mark)
                continue
        if text.startswith('![', i):
            node = link_at(text, i, refs)
            if node:
                result.append(node[2])
                i = node[-1]
                continue
        i += 1
    return result


def inline(text, refs=None, media_url=None):
    refs = refs or {}
    out = []
    i = 0
    while i < len(text):
        c = text[i]
        if c == '\\' and i + 1 < len(text):
            if text[i + 1] in _PUNCT:
                out.append(text_escape(text[i + 1]))
                i += 2
                continue
            if text[i + 1] == '\n':
                out.append('<br />\n')
                i += 2
                continue
        if c == '`':
            mark = re.match(r'`+', text[i:]).group(0)
            end = text.find(mark, i + len(mark))
            if end >= 0:
                val = text[i + len(mark):end].replace('\n', ' ')
                if val.startswith(' ') and val.endswith(' ') and val.strip():
                    val = val[1:-1]
                out.append('<code>' + text_escape(val) + '</code>')
                i = end + len(mark)
                continue
        if c == '$':
            mark = '$$' if text.startswith('$$', i) else '$'
            end = text.find(mark, i + len(mark))
            if end >= 0 and (len(mark) == 2 or (i + 1 < len(text) and not text[i + 1].isspace())):
                typ = 'display' if len(mark) == 2 else 'inline'
                val = text[i + len(mark):end]
                out.append('<span class="math math-%s">%s</span>' % (typ, text_escape(val)))
                i = end + len(mark)
                continue
        if c == '[' or text.startswith('![', i):
            node = link_at(text, i, refs)
            if node:
                image, label, url, title, finish = node
                if image:
                    url = media_url(url) if media_url else url
                    extension = url.rsplit('.', 1)[-1].lower()
                    if extension in ('mp3', 'wav', 'ogg', 'm4a', 'flac', 'aac', 'opus'):
                        out.append('<audio controls src="%s" title="%s"></audio>' % (attr(url), attr(title)))
                    elif extension in ('mp4', 'webm', 'mov'):
                        out.append('<video controls src="%s" title="%s"></video>' % (attr(url), attr(title)))
                    else:
                        label = re.sub(r'<[^>]*>', '', inline(label, refs))
                        label = html.unescape(label)
                        out.append('<img src="%s" alt="%s"%s />' % (attr(url), attr(label), (' title="' + attr(title) + '"') if title else ''))
                else:
                    out.append('<a href="%s"%s>%s</a>' % (attr(url), (' title="' + attr(title) + '"') if title else '', inline(label, refs, media_url)))
                i = finish
                continue
        found = False
        for mark, tag in (('***', 'strongem'), ('___', 'strongem'), ('**', 'strong'), ('__', 'strong'), ('~~', 'del'), ('*', 'em'), ('_', 'em')):
            if text.startswith(mark, i) and i + len(mark) < len(text) and not text[i + len(mark)].isspace():
                if mark.startswith('_') and i > 0 and text[i - 1].isalnum():
                    continue
                end = text.find(mark, i + len(mark))
                if end >= 0 and not text[end - 1].isspace():
                    value = inline(text[i + len(mark):end], refs, media_url)
                    out.append('<strong><em>' + value + '</em></strong>' if tag == 'strongem' else '<%s>%s</%s>' % (tag, value, tag))
                    i = end + len(mark)
                    found = True
                    break
        if found:
            continue
        if c == '<':
            m = re.match(r'<((?:https?://|mailto:)[^<> ]+)>', text[i:])
            if m:
                target = m.group(1)
                out.append('<a href="%s">%s</a>' % (attr(target), text_escape(target.removeprefix('mailto:'))))
                i += len(m.group(0))
                continue
            m = re.match(r'(?:</?[A-Za-z][^>]*>|<!--.*?-->)', text[i:], re.S)
            if m:
                out.append(m.group(0))
                i += len(m.group(0))
                continue
        if c == '&':
            m = re.match(r'&(?:#[0-9]+|#x[0-9a-fA-F]+|[a-zA-Z][a-zA-Z0-9]+);', text[i:])
            if m:
                out.append(text_escape(html.unescape(m.group(0))))
                i += len(m.group(0))
                continue
        if c == '\n':
            if i >= 2 and text[i - 2:i] == '  ':
                while out and out[-1] == ' ':
                    out.pop()
                out.append('<br />\n')
            else:
                out.append('\n')
        else:
            out.append(text_escape(c))
        i += 1
    return ''.join(out)


def render(text, media_url=None):
    text, refs = references(text)
    return _blocks(text.split('\n'), refs, media_url)


def _blocks(lines, refs, media_url):
    out = []
    i = 0
    def fmt(t):
        return inline(t, refs, media_url)
    def starter(line):
        return re.match(r'^ {0,3}(?:#{1,6}\s|>|`{3,}|~{3,}|[-+*]\s|\d+[.)]\s)', line) or re.match(r'^ {0,3}(?:\*\s*){3,}$|^ {0,3}(?:-\s*){3,}$|^ {0,3}(?:_\s*){3,}$', line)
    while i < len(lines):
        line = lines[i]
        if not line.strip():
            i += 1
            continue
        m = re.match(r'^ {0,3}(`{3,}|~{3,})(.*)$', line)
        if m:
            fence, lang = m.groups()
            lang = unescape(lang.strip().split()[0]) if lang.strip() else ''
            i += 1
            code = []
            while i < len(lines):
                if re.match(r'^ {0,3}' + re.escape(fence[0]) + '{' + str(len(fence)) + r',}\s*$', lines[i]):
                    i += 1
                    break
                code.append(lines[i])
                i += 1
            out.append('<pre><code' + (' class="language-' + attr(lang) + '"' if lang else '') + '>' + text_escape('\n'.join(code) + ('\n' if code else '')) + '</code></pre>\n')
            continue
        if line.startswith(('    ', '\t')):
            code = []
            while i < len(lines) and (lines[i].startswith(('    ', '\t')) or not lines[i].strip()):
                code.append(lines[i][1:] if lines[i].startswith('\t') else lines[i][4:])
                i += 1
            while code and not code[-1]:
                code.pop()
            out.append('<pre><code>' + text_escape('\n'.join(code) + '\n') + '</code></pre>\n')
            continue
        m = re.match(r'^ {0,3}(#{1,6})(?:\s+(.*?)\s*#*\s*|$)', line)
        if m:
            level = len(m.group(1))
            out.append('<h%d>%s</h%d>\n' % (level, fmt((m.group(2) or '').strip()), level))
            i += 1
            continue
        if i + 1 < len(lines) and re.match(r'^ {0,3}(?:=+|-+)\s*$', lines[i + 1]):
            level = 1 if lines[i + 1].lstrip().startswith('=') else 2
            out.append('<h%d>%s</h%d>\n' % (level, fmt(line.strip()), level))
            i += 2
            continue
        if re.match(r'^ {0,3}(?:\*\s*){3,}$|^ {0,3}(?:-\s*){3,}$|^ {0,3}(?:_\s*){3,}$', line):
            out.append('<hr />\n')
            i += 1
            continue
        if re.match(r'^ {0,3}>', line):
            quote = []
            while i < len(lines) and re.match(r'^ {0,3}>', lines[i]):
                quote.append(re.sub(r'^ {0,3}> ?', '', lines[i]))
                i += 1
            out.append('<blockquote>\n' + _blocks(quote, refs, media_url) + '</blockquote>\n')
            continue
        m = re.match(r'^ {0,3}([-+*]|\d+[.)])\s+(.*)$', line)
        if m:
            ordered = len(m.group(1)) > 1
            tag = 'ol' if ordered else 'ul'
            number = int(m.group(1)[:-1]) if ordered else 1
            out.append('<' + tag + (' start="%d"' % number if number != 1 else '') + '>\n')
            while i < len(lines):
                item = re.match(r'^ {0,3}([-+*]|\d+[.)])\s+(.*)$', lines[i])
                if not item or (len(item.group(1)) > 1) != ordered:
                    break
                value = [item.group(2)]
                i += 1
                while i < len(lines) and lines[i].strip() and not starter(lines[i]):
                    value.append(lines[i].strip())
                    i += 1
                out.append('<li>' + fmt('\n'.join(value)) + '</li>\n')
            out.append('</' + tag + '>\n')
            continue
        if re.match(r'^ {0,3}<(?:div|table|script|style|pre|section|h[1-6]|!--)(?:\s|>|$)', line, re.I):
            raw = []
            while i < len(lines) and lines[i].strip():
                raw.append(lines[i])
                i += 1
            out.append('\n'.join(raw) + '\n')
            continue
        paragraph = [line.strip()]
        i += 1
        while i < len(lines) and lines[i].strip() and not starter(lines[i]):
            paragraph.append(lines[i].lstrip())
            i += 1
        out.append('<p>' + fmt('\n'.join(paragraph)) + '</p>\n')
    return ''.join(out)
