                out.append('<br />\n')
            else:
                out.append('\n')
        else:
            out.append(text_escape(c))
        i += 1
    return ''.join(out)


def render(text, media_url=None):
    text, refs = references(text)
    return _blocks(text.split('\n'), refs, media_url)


def _blocks(lines, refs, media_url):
