        if line.startswith(('    ', '\t')):
            code = []
            while i < len(lines) and (lines[i].startswith(('    ', '\t')) or not lines[i].strip()):
                code.append(lines[i][1:] if lines[i].startswith('\t') else lines[i][4:])
