            level = len(m.group(1))
            out.append('<h%d>%s</h%d>\n' % (level, fmt((m.group(2) or '').strip()), level))
            i += 1
            continue
        if i + 1 < len(lines) and re.match(r'^ {0,3}(?:=+|-+)\s*$', lines[i + 1]):
            level = 1 if lines[i + 1].lstrip().startswith('=') else 2
            out.append('<h%d>%s</h%d>\n' % (level, fmt(line.strip()), level))
            i += 2
            continue
