                    break
                value = [item.group(2)]
                i += 1
                while i < len(lines) and lines[i].strip() and not starter(lines[i]):
                    value.append(lines[i].strip())
                    i += 1
                out.append('<li>' + fmt('\n'.join(value)) + '</li>\n')
            out.append('</' + tag + '>\n')
            continue
        if re.match(r'^ {0,3}<(?:div|table|script|style|pre|section|h[1-6]|!--)(?:\s|>|$)', line, re.I):
            raw = []
            while i < len(lines) and lines[i].strip():
                raw.append(lines[i])
                i += 1
            out.append('\n'.join(raw) + '\n')
            continue
        paragraph = [line.strip()]
        i += 1
        while i < len(lines) and lines[i].strip() and not starter(lines[i]):
            paragraph.append(lines[i].lstrip())
            i += 1
        out.append('<p>' + fmt('\n'.join(paragraph)) + '</p>\n')
    return ''.join(out)
