                    self.error('Cannot overwrite a value')
                node[key[-1]] = value
                self.whitespace()
                if self.i < len(self.text) and self.text[self.i] == ',':
                    self.i += 1
                elif self.i >= len(self.text) or self.text[self.i] != '}':
                    self.error('Unclosed inline table')
        start = self.i
        m = re.match(r'[^\s,\]}#]+', self.text[self.i:])
        token = m.group() if m else ''
        self.i += len(token)
        if token == 'true':
            return True
        if token == 'false':
            return False
        t = token.replace('_', '')
        try:
            if re.fullmatch(r'[+-]?(?:0|[1-9][0-9]*)', t):
                return int(t)
            if re.fullmatch(r'0[xob][0-9a-fA-F]+', t):
