import datetime
import re
import sqlite3
from errors import AppError, invalid_hash, sqlite_error, quoted

_SCHEMA = '''
CREATE TABLE cards (
    card_hash text primary key,
    added_at text not null,
    last_reviewed_at text,
    stability real,
    difficulty real,
    interval_raw real,
    interval_days integer,
    due_date text,
