"""The small TOML reader used on Python installations older than 3.11."""
import re
import datetime


class TOMLDecodeError(ValueError):
    pass


class Reader:
    def __init__(self, text):
        self.text = text
        self.i = 0

    def error(self, message, at=None):
        at = self.i if at is None else at
        row = self.text.count('\n', 0, at) + 1
        col = at - self.text.rfind('\n', 0, at)
        raise TOMLDecodeError('%s (at line %d, column %d)' % (message, row, col))

    def whitespace(self, multiline=False):
        while self.i < len(self.text):
            c = self.text[self.i]
            if c in (' \t\r\n' if multiline else ' \t\r'):
                self.i += 1
            elif c == '#' and multiline:
                while self.i < len(self.text) and self.text[self.i] != '\n':
                    self.i += 1
            else:
                break

    def string(self):
        quote = self.text[self.i]
        triple = self.text.startswith(quote * 3, self.i)
        mark = quote * (3 if triple else 1)
        self.i += len(mark)
        if triple and self.i < len(self.text) and self.text[self.i] == '\n':
            self.i += 1
        out = []
        while self.i < len(self.text):
            if self.text.startswith(mark, self.i):
                self.i += len(mark)
                return ''.join(out)
            c = self.text[self.i]
            self.i += 1
            if c == '\n' and not triple:
                self.error('Illegal character in string')
            if c == '\\' and quote == '"':
                if self.i == len(self.text):
                    self.error('Unterminated string')
                e = self.text[self.i]
                self.i += 1
                escapes = {'b': '\b', 't': '\t', 'n': '\n', 'f': '\f', 'r': '\r', '"': '"', '\\': '\\'}
                if e in escapes:
                    out.append(escapes[e])
                elif e in 'uU':
                    size = 4 if e == 'u' else 8
                    try:
                        out.append(chr(int(self.text[self.i:self.i + size], 16)))
                    except (ValueError, OverflowError):
                        self.error('Invalid hex value')
                    self.i += size
                elif triple and e.isspace():
                    self.whitespace(True)
                else:
                    self.error('Unescaped backslash in a string', self.i - 1)
            else:
                out.append(c)
        self.error('Unterminated string')

    def key(self):
        result = []
        while True:
            self.whitespace()
            if self.i < len(self.text) and self.text[self.i] in "'\"":
                result.append(self.string())
            else:
                m = re.match(r'[A-Za-z0-9_-]+', self.text[self.i:])
                if not m:
                    self.error('Invalid statement')
                result.append(m.group())
                self.i += len(m.group())
            self.whitespace()
            if self.i < len(self.text) and self.text[self.i] == '.':
                self.i += 1
                continue
            return result

    def value(self):
        self.whitespace()
        if self.i >= len(self.text):
            self.error('Invalid value')
        c = self.text[self.i]
        if c in "'\"":
            return self.string()
        if c == '[':
            self.i += 1
            result = []
            while True:
                self.whitespace(True)
                if self.i < len(self.text) and self.text[self.i] == ']':
                    self.i += 1
                    return result
                result.append(self.value())
                self.whitespace(True)
                if self.i < len(self.text) and self.text[self.i] == ',':
                    self.i += 1
                elif self.i >= len(self.text) or self.text[self.i] != ']':
                    self.error('Unclosed array')
        if c == '{':
            self.i += 1
            result = {}
            while True:
                self.whitespace()
                if self.i < len(self.text) and self.text[self.i] == '}':
                    self.i += 1
                    return result
                key = self.key()
                if self.i >= len(self.text) or self.text[self.i] != '=':
                    self.error("Expected '=' after a key in a key/value pair")
                self.i += 1
                value = self.value()
                node = result
                for k in key[:-1]:
                    node = node.setdefault(k, {})
                if key[-1] in node:
                    self.error('Cannot overwrite a value')
                node[key[-1]] = value
                self.whitespace()
                if self.i < len(self.text) and self.text[self.i] == ',':
                    self.i += 1
                elif self.i >= len(self.text) or self.text[self.i] != '}':
                    self.error('Unclosed inline table')
        start = self.i
        m = re.match(r'[^\s,\]}#]+', self.text[self.i:])
        token = m.group() if m else ''
        self.i += len(token)
        if token == 'true':
            return True
        if token == 'false':
            return False
        t = token.replace('_', '')
        try:
            if re.fullmatch(r'[+-]?(?:0|[1-9][0-9]*)', t):
                return int(t)
            if re.fullmatch(r'0[xob][0-9a-fA-F]+', t):
                return int(t, 0)
            if re.fullmatch(r'[+-]?(?:\d+(?:\.\d+)?(?:[eE][+-]?\d+)?|inf|nan)', t):
                return float(t)
            if re.match(r'^\d{4}-\d\d-\d\d', t):
                return datetime.datetime.fromisoformat(t.replace('Z', '+00:00')) if 'T' in t else datetime.date.fromisoformat(t)
        except ValueError:
            pass
        self.error('Invalid value', start)

    def read(self):
        result = {}
        table = result
        while True:
            self.whitespace(True)
            if self.i >= len(self.text):
                return result
            if self.text[self.i] == '[':
                array = self.text.startswith('[[', self.i)
                self.i += 2 if array else 1
                keys = self.key()
                ending = ']]' if array else ']'
                if not self.text.startswith(ending, self.i):
                    self.error("Expected ']' at the end of a table declaration")
                self.i += len(ending)
                table = result
                for k in keys[:-1]:
                    table = table.setdefault(k, {})
                if array:
                    items = table.setdefault(keys[-1], [])
                    items.append({})
                    table = items[-1]
                else:
                    table = table.setdefault(keys[-1], {})
            else:
                at = self.i
                keys = self.key()
                if self.i >= len(self.text) or self.text[self.i] != '=':
                    self.error("Expected '=' after a key in a key/value pair")
                self.i += 1
                value = self.value()
                node = table
                for k in keys[:-1]:
                    node = node.setdefault(k, {})
                if keys[-1] in node:
                    self.error('Cannot overwrite a value', at)
                node[keys[-1]] = value
            self.whitespace()
            if self.i < len(self.text) and self.text[self.i] == '#':
                while self.i < len(self.text) and self.text[self.i] != '\n':
                    self.i += 1
            if self.i < len(self.text) and self.text[self.i] != '\n':
                self.error('Expected newline or end of document after a statement')
            if self.i < len(self.text):
                self.i += 1


def loads(text):
    return Reader(text).read()
