import os
import struct
from pathlib import Path
from database import Database
from digest import blake3
from errors import AppError, io_error
from frontmatter import lines_of, parse_frontmatter
from markup import media_references


def parse_cloze(source):
    output = []
    spans = []
    length = 0
    start = None
    i = 0
    while i < len(source):
        c = source[i]
        if c == '\\' and i + 1 < len(source) and source[i + 1] in '[]':
            output.append(source[i + 1])
            length += 1
            i += 2
            continue
        if source.startswith('![', i):
            end = source.find(']', i + 2)
            if end >= 0:
                text = source[i:end + 1]
                output.append(text)
                length += len(text.encode())
                i = end + 1
                continue
        if c == '[':
            start = length
        elif c == ']':
            if start is not None:
                spans.append((start, (length - 1) & ((1 << 64) - 1)))
                start = None
        else:
            output.append(c)
            length += len(c.encode())
        i += 1
    return ''.join(output), spans


def read_text(path):
    try:
        return Path(path).read_bytes().decode('utf-8')
    except (OSError, UnicodeError) as exc:
        raise io_error(exc)


def parse_deck(path):
    name, lines = parse_frontmatter(lines_of(read_text(path)), path.stem)
    state = None
    first = 0
    question = []
    answer = []
    cloze = []
    cards = []

    def error(message, line):
        raise AppError('Parse error: %s. Location: %s:%d' % (message, path, line + 1))

    def card(content, key, family, last):
        cards.append(dict(hash=key, familyHash=family, deckName=name,
                          location=dict(filePath=str(path), lineStart=first, lineEnd=last),
                          content=content, performance=None))

    def finish(last):
        if state == 'answer':
            q = '\n'.join(question).strip()
            a = '\n'.join(answer).strip()
            key = blake3(('Basic' + q + a).encode())
            card(dict(basic=dict(question=q, answer=a)), key, None, last)
        elif state == 'cloze':
            text, spans = parse_cloze('\n'.join(cloze).strip())
            if not spans:
                error('Cloze card must contain at least one cloze deletion', first)
            stem = ('Cloze' + text).encode()
            family = blake3(stem)
            for start, end in spans:
                key = blake3(stem + struct.pack('<QQ', start, end))
                card(dict(cloze=dict(text=text, start=start, end=end)), key, family, last)

    for number, line in enumerate(lines):
        if line.startswith('Q:'):
            if state == 'question':
                error('New question without answer', number)
            finish(number)
            state = 'question'
            first = number
            question = [line[2:].strip()]
            answer = []
        elif line.startswith('A:'):
            if state is None:
                error('Found answer tag without a question', number)
            if state == 'answer':
                error('Found answer tag while reading an answer', number)
            if state == 'cloze':
                error('Found answer tag while reading a cloze card', number)
            state = 'answer'
            answer = [line[2:].strip()]
        elif line.startswith('C:'):
            if state == 'question':
                error('Found cloze tag while reading a question', number)
            finish(number)
            state = 'cloze'
            first = number
            cloze = [line[2:].strip()]
        elif line.strip() == '---':
            if state == 'question':
                error('Found flashcard separator while reading a question', number)
            finish(number)
            state = None
        elif state == 'question':
            question.append(line)
        elif state == 'answer':
            answer.append(line)
        elif state == 'cloze':
            cloze.append(line)
    if state == 'question':
        error('File ended while reading a question without an answer', len(lines) - 1)
    finish(len(lines) - 1)
    return cards


class Collection:
    def __init__(self, directory):
        if not os.path.exists(directory):
            raise AppError('directory does not exist.')
        self.root = Path(os.path.realpath(directory))
        self.db = Database(self.root / 'hashcards.db')
        self.cards = {}
        self.macros = []
        macrofile = self.root / 'macros.tex'
        if macrofile.exists():
            for line in lines_of(read_text(macrofile)):
                if not line.startswith('%') and ' ' in line:
                    self.macros.append(tuple(line.split(' ', 1)))
        self._walk(self.root, set())
        self.cards = dict(sorted(self.cards.items()))
        self.check_media()

    def _walk(self, folder, seen):
        real = os.path.realpath(folder)
        if real in seen:
            return
        seen.add(real)
        try:
            entries = list(os.scandir(folder))
        except OSError as exc:
            raise io_error(exc)
        for entry in entries:
            try:
                if entry.is_dir():
                    self._walk(Path(entry.path), seen)
                elif entry.is_file() and Path(entry.name).suffix == '.md':
                    path = Path(os.path.realpath(entry.path))
                    try:
                        path.relative_to(self.root)
                    except ValueError:
                        raise AppError('Strip prefix error: StripPrefixError(\n    (),\n)')
                    for card in parse_deck(path):
                        self.cards.setdefault(card['hash'], card)
            except OSError as exc:
                raise io_error(exc)

    def media_path(self, uri, card):
        if uri.startswith('@/'):
            return self.root / uri[2:]
        return Path(card['location']['filePath']).parent / uri

    def check_media(self):
        missing = set()
        for card in self.cards.values():
            content = card['content']
            texts = content['basic'].values() if 'basic' in content else [content['cloze']['text']]
            for text in texts:
                for uri in media_references(text):
                    path = self.media_path(uri, card)
                    if not path.is_file():
                        missing.add((uri, card['location']['filePath'], card['location']['lineStart']))
        if missing:
            message = 'Missing media files referenced in cards:\n'
            for uri, path, line in sorted(missing):
                message += '  - %s (referenced in %s:%d)\n' % (uri, path, line)
            raise AppError(message)

    def statistics(self):
        return dict(cardsInDeckCount=len(self.cards), cardsInDbCount=len(self.db.hashes()),
                    texMacroCount=len(self.macros), cardsReviewedTodayCount=self.db.reviewed_today())

    def export(self):
        cards = []
        for key, card in self.cards.items():
            c = dict(card)
            c['performance'] = self.db.performance(key)
            cards.append(c)
        return dict(cards=cards, sessions=self.db.sessions())

    def orphans(self):
        return [key for key in self.db.hashes() if key not in self.cards]
