class Session:
    def __init__(self, collection, options):
        self.collection = collection
        self.options = options
        self.started = now()
        self.ended = None
        self.collection.db.sync(self.collection.cards, self.started)
        self.performances = {key: self.collection.db.performance(key) for key in self.collection.cards}
        self.queue = select_cards(collection, options, self.started, self.performances)
        self.total = len(self.queue)
        self.completed = 0
        self.revealed = False
        self.reviews = []
        self.undo = []
        self.port = options.get('port', 8000)

    def finish(self, when=None):
        self.ended = when or now()
        self.collection.db.save_session(self.started, self.ended, self.reviews, self.performances)

    def action(self, action):
        if action == 'End':
            self.finish()
        elif self.ended is not None:
            return
        elif action == 'Reveal':
            self.revealed = True
        elif action == 'Undo':
            if self.undo:
                queue, completed, key, previous, review_count = self.undo.pop()
                self.queue = queue
                self.completed = completed
                self.performances[key] = previous
                self.reviews = self.reviews[:review_count]
                self.revealed = False
        elif action in ('Forgot', 'Hard', 'Good', 'Easy') and self.revealed and self.queue:
            key = self.queue[0]
            self.undo.append((list(self.queue), self.completed, key, self.performances[key], len(self.reviews)))
            when = now()
            p = schedule(self.performances[key], action, when)
            self.performances[key] = p
            self.reviews.append((key, action, p))
            self.queue.pop(0)
            self.revealed = False
            if action in ('Forgot', 'Hard'):
                self.queue.append(key)
            else:
                self.completed += 1
            if not self.queue:
                self.finish(when)

    def media_url(self, card, uri):
        file = os.path.normpath(self.collection.media_path(uri, card))
        rel = os.path.relpath(file, self.collection.root)
        return 'http://localhost:%d/file/%s' % (self.port, urllib.parse.quote(rel, safe="/:%@-._~?&=+#"))

    def page(self):
        if self.ended is not None:
            return self.finished_page()
        card = self.collection.cards[self.queue[0]]
        url = lambda uri: self.media_url(card, uri)
        body = '<div class="root"><div class="header"><div class="progress-bar"><div class="progress-fill" style="width: '
        percentage = self.completed / self.total * 100 if self.total else 0
        body += ('%g' % percentage) + '%;"></div></div></div><div class="card-container"><div class="card"><div class="card-header"><h1>'
        body += attr(card['deckName']) + '</h1></div><div class="card-content">'
