"""Review scheduling and deterministic selection of today's cards."""
import datetime
import math
from database import stamp

_INITIAL_S = (0.40255, 1.18385, 3.173, 15.69105)
_INITIAL_D = (7.1949, 6.488305268471453, 5.282434422319005, 3.2245015893713678)
_FACTOR = 19.0 / 81.0


def schedule(previous, grade, when):
    number = ('Forgot', 'Hard', 'Good', 'Easy').index(grade) + 1
    if previous is None:
        stability = _INITIAL_S[number - 1]
        difficulty = _INITIAL_D[number - 1]
        count = 1
    else:
        stability = previous['stability']
        difficulty = previous['difficulty']
        elapsed = (when.date() - datetime.datetime.fromisoformat(previous['lastReviewedAt']).date()).days
        retention = (1 + _FACTOR * max(0, elapsed) / stability) ** -0.5
        if grade == 'Forgot':
            updated = (1.9395 * difficulty ** -0.11 * ((stability + 1) ** 0.29605 - 1)
                       * math.exp(2.2698 * (1 - retention)))
            stability = min(stability, updated)
        else:
            penalty = 0.2315 if grade == 'Hard' else 1.0
            bonus = 2.9898 if grade == 'Easy' else 1.0
            stability *= (1 + math.exp(1.54575) * (11 - difficulty) * stability ** -0.1192
                          * (math.exp(1.01925 * (1 - retention)) - 1) * penalty * bonus)
        delta = -1.4604 * (number - 3)
        difficulty = 0.0046 * _INITIAL_D[3] + (1 - 0.0046) * (difficulty + delta * (10 - difficulty) / 9)
        difficulty = min(10.0, max(1.0, difficulty))
        stability = max(0.01, stability)
        count = previous['reviewCount'] + 1
    interval = stability / _FACTOR * (0.9 ** -2.0 - 1.0)
    days = max(1, min(36500, math.floor(interval + 0.5)))
    return dict(lastReviewedAt=stamp(when), stability=stability, difficulty=difficulty,
                intervalRaw=interval, intervalDays=days,
                dueDate=(when.date() + datetime.timedelta(days=days)).isoformat(), reviewCount=count)


def select_cards(collection, options, when, performances):
    selected = []
    families = set()
    new_count = 0
    today = when.date().isoformat()
    limit = options.get('card-limit', (1 << 64) - 1)
    new_limit = options.get('new-card-limit', (1 << 64) - 1)
    for key, card in collection.cards.items():
        if len(selected) >= limit:
            break
        if 'from-deck' in options and card['deckName'] != options['from-deck']:
            continue
        p = performances[key]
        if p is not None and p['dueDate'] > today:
            continue
        if p is None and new_count >= new_limit:
            continue
        family = card['familyHash']
        if options.get('bury-siblings', 'true') == 'true' and family is not None:
            if family in families:
                continue
            families.add(family)
        selected.append(key)
        if p is None:
            new_count += 1
    return selected
