class Handler(http.server.BaseHTTPRequestHandler):
    protocol_version = 'HTTP/1.1'

    def log_message(self, *args):
        pass

    def respond(self, status, body=b'', content_type=None, headers=None):
        if isinstance(body, str):
            body = body.encode('utf-8')
        self.send_response_only(status)
        if content_type:
            self.send_header('content-type', content_type)
        for key, value in (headers or {}).items():
            self.send_header(key, value)
        self.send_header('content-length', str(len(body)))
        if self.headers.get('Connection', '').lower() == 'close':
            self.send_header('connection', 'close')
        self.send_header('date', self.date_time_string())
        self.end_headers()
        if self.command != 'HEAD':
            try:
                self.wfile.write(body)
                self.wfile.flush()
            except (BrokenPipeError, ConnectionResetError):
                pass

    def do_HEAD(self):
        self.do_GET()

    def do_GET(self):
        route = urllib.parse.urlsplit(self.path).path
        state = self.server.state
        if route == '/':
            return self.respond(200, state.page(), 'text/html; charset=utf-8')
        if route == '/style.css':
            return self.respond(200, _CSS, 'text/css')
        if route == '/script.js':
            macros = dict(state.collection.macros)
            script = _SCRIPT.replace('MACROS', json.dumps(macros))
            return self.respond(200, script, 'text/javascript')
        if route == '/katex/katex.css':
            return self.respond(200, '.math-display { display: block; text-align: center; }\n', 'text/css')
        if route in ('/katex/katex.js', '/katex/mhchem.js'):
            return self.respond(200, '', 'text/javascript')
        if route.startswith('/file/') and len(route) > 6:
            relative = urllib.parse.unquote(route[6:])
            path = state.collection.root / relative
            if '..' in Path(relative).parts or relative.startswith('/'):
                return self.respond(404, 'Not Found', 'text/plain')
            try:
                data = path.read_bytes()
            except OSError:
                return self.respond(404, 'Not Found', 'text/plain')
            mime = {'.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.png': 'image/png', '.gif': 'image/gif',
                    '.svg': 'image/svg+xml', '.webp': 'image/webp', '.mp3': 'audio/mpeg', '.wav': 'audio/wav',
                    '.ogg': 'audio/ogg', '.mp4': 'video/mp4', '.webm': 'video/webm'}.get(path.suffix.lower(), 'application/octet-stream')
            return self.respond(200, data, mime)
        self.respond(404, 'Not Found', 'text/html; charset=utf-8')

    def do_POST(self):
        length = int(self.headers.get('Content-Length', '0'))
        body = self.rfile.read(length)
        if urllib.parse.urlsplit(self.path).path != '/':
            return self.respond(404, 'Not Found', 'text/html; charset=utf-8')
        if self.headers.get('Content-Type', '').split(';')[0].strip() != 'application/x-www-form-urlencoded':
            return self.respond(415, 'Form requests must have `Content-Type: application/x-www-form-urlencoded`', 'text/plain; charset=utf-8')
        form = urllib.parse.parse_qs(body.decode('utf-8', errors='replace'), keep_blank_values=True)
        if 'action' not in form:
            error = 'missing field `action`'
        elif len(form['action']) > 1:
            error = 'duplicate field `action`'
        else:
            action = form['action'][0]
            if action not in ('Reveal', 'Undo', 'End', 'Forgot', 'Hard', 'Good', 'Easy', 'Shutdown'):
                error = 'action: unknown variant `%s`, expected one of `Reveal`, `Undo`, `End`, `Forgot`, `Hard`, `Good`, `Easy`, `Shutdown`' % action
            else:
                error = None
        if error:
            return self.respond(422, 'Failed to deserialize form body: ' + error, 'text/plain; charset=utf-8')
